// The US text, for lettering the unmodded game in the Text mod's fonts.
// Written by tools/build_us_text.py from the translation workbook's
// "Current US" column: edit the workbook (or the tool's rules) and run it again.
using System.Collections.Generic;

namespace Kf3.Mods.Text;

static class UsText
{
    /// <summary>Every sign, dialogue line, card and description, by its US disc
    /// entry: T = TALK.T (and the same page of STALK.T, the log), I = ITEM.T.</summary>
    public static readonly Dictionary<string, string> Pictures = new()
    {
        ["T0"] = "If you see something you like...\ntake it -- this stuff is just\ngoing to go to waste with no\ncustomers to buy anything....\nAnyway, I'll probably be dead by\nthe time anyone comes around\nhere again...",
        ["T1"] = "You know, having a decent weapon\naround here wouldn't be a bad\nidea. I wouldn't suggest going\nagainst those demons on purpose,\nbut...oh you are?...Sorry.",
        ["T2"] = "Another demon fighter, eh?\nHmph...There hasn't been one of\nthose around here since the great\nCommander, David Silviera\ndisappeared.",
        ["T3"] = "The villagers around here\nfollowed him and fought at his\nside as his soldiers (poor saps)\n...they were so grateful to him\nthat they carved a stone monument\nin his honor. He was the greatest\nhope for our kingdom's peace.",
        ["T4"] = "But now he's gone....Since\nSilviera's disappearance, the\nsituation here has been getting\nworse every day....Soon there\nwill be nothing left here but the\nminions of evil.",
        ["T5"] = "If you plan on going to that\ncastle, be forewarned, Silviera\ndisappeared when he went to that\nevil place. He went in and just\nhasn't been seen since. With him,\ndied the last hopes of this\nstrangling kingdom.",
        ["T6"] = "If only I had some money I'd go\nto Granatyki to be with\nmy family...",
        ["T7"] = "My family fled to the neighboring\nkingdom when the monsters started\nto come out. I'm the only one\nleft here now, and I can't go\nanywhere because all the roads\nare closed.",
        ["T8"] = "When I followed Leon to this\nplace, these villages were full\nof people...positive energy,\nhelping hands...it was like a\ndream. Fitting that a dream\nshould turn to a nightmare...",
        ["T9"] = "Recently the evil creatures began\nto appear again. Families fled\nfor their lives. The villages are\nnearly empty now...no one dares\nto even go outside anymore, the\nstreets just aren't safe with\nthose creatures around.",
        ["T10"] = "I wonder if I'll ever see the\ntime when peace and vitality\nreturn to this place...it's so\nlonely here -- no family, no\nvisitors...sometimes I almost\nwish...no, I mustn't give up hope\ntoo....",
        ["T11"] = "I hope you can bring the peace\nand beauty back to our kingdom\n-- demon fighter.\nI wish I could see my family just\none last time....",
        ["T16"] = "I don't know where you're\nheaded, but you should be a\nlittle more prepared if you want\nto stay alive out there.",
        ["T17"] = "Blood sucking plant? Ya', I've\nseen 'em -- not like it'll do you\nany good though...I saw one over\nby the lava at the cliff.",
        ["T18"] = "I wouldn't go there if I were you\n-- the monsters are there...just\nwaiting for the poor sap who\nneeds that precious herb -- you'd\nhave to have a death wish to\nsearch them out on purpose.\nHey, wait a minute, I know you!",
        ["T19"] = "You're Austin Lyle Forester,\nPrince of Verdite! I met you at\nthe castle a long time ago -- we\nused to play together when my\nfather and I visited the castle--\nI know you go by Prince Lyle now,\nbut can I still call you Austin?",
        ["T20"] = "You know, everyone around here\nhates the king now. But I just\ncan't believe that someone so\nkind could have changed so\ndrastically for the worse--\nwhat happened? He was such a\nstrong and wonderful king.",
        ["T21"] = "I know I may not look very\nstrong, but underneath, I'm\nactually very tough.... I'm the\nonly one around here who can go\nout in this area without getting\nmyself killed. I've had to...ever\nsince my father disappeared.",
        ["T22"] = "I know it's dangerous, but I\ncan't just sit here waiting for\nmy death like the rest of these\ncowards. Somehow I have to find\nmy father.... You're looking for\nthe key of Ichrius, Right?",
        ["T23"] = "If only father were back, I might\nbe able to help -- I think he\nused to have one of the pieces\nto the key that belonged to\nIchrius himself. But Father went\nto Garan in search of Promeus...\nhe just never came back.",
        ["T24"] = "Promeus is the special metal\nwhich was handed down by the\nDwarfs. I know it's precious, but\nI don't think it is worth risking\nour lives for. Of course Father\nhad a very different view--",
        ["T25"] = "Anything for a buck...especially\nfor a fortune! I hear Garan is a\nvery dangerous place. I can't\nhelp worrying about my father's\nsafety. He's not as young as he\nused to be.",
        ["T26"] = "My father was very close to the\nking in my childhood. That's why\nwe used to go to the castle so\noften--My father would chat with\nthe king about traveling and\nsuch. He used to be such a nice\nman.",
        ["T27"] = "While my father was chatting with\nthe king, I used to take walks\nwith Alexander in the courtyard.\nThe flowers would be blooming.\nIt was always so beautiful! That\nis actually where Alexander\nintroduced me to you...",
        ["T28"] = "Ahh...Those were the good\nold days! Walks, laughter, games\nwith the prince...you were my\nbest friend back then, you know.\nWhat with all the traveling, I\ndidn't have many friends.",
        ["T29"] = "You mean the spring beyond the\nlava river? We call it the\nSpring of Ichrius. We Elves are\nactually the only ones with any\nknowledge about Ichrius.",
        ["T30"] = "You see, Ichrius found the tree\nof the Dragon King Plant. That's\nwhere everything started. We\ndon't know exactly what kind of\npower he left behind, but we do\nknow that we have to have the key\nto obtain it.",
        ["T31"] = "If there's anything at all I can\ndo for you, please let me know.\nGood luck!",
        ["T32"] = "Ichrius gave the High Elves\nguidance and taught them various\ntricks. Their life together was\nwell-organized.",
        ["T33"] = "Orladin, the High Archmage,\nsucceeded Ichrius. But, Orladin\nbegan to stay inside the Maze\nTemple he built. Gradually, the\nElves lost contact with him.",
        ["T34"] = "The Elves who dwelt in the woods\nbegan to worship Seath and built\nseveral temples.",
        ["T35"] = "They say Seath is good and Guyra\nis evil, but I don't believe it.\nFor some reason, Seath rendered\nhis help to the Elves, but I\nstill can't believe he did it\nwith good intentions.",
        ["T36"] = "Orladin must have known the\ncircumstances well.",
        ["T37"] = "I'm so glad to see you again!\nI knew you'd be around here\nsomewhere.",
        ["T38"] = "You look like you've found some\ntrouble, you should be more\ncareful.",
        ["T39"] = "Here, take the key to my house.\nGo there and look for my staff.\nThe king gave it to me as a gift,\nbut I have no need for it now.\nTake it with you for\nprotection...maybe it will bring\nyou luck.",
        ["T40"] = "This is where I grew up. When\nI was a child, Marilyn used to\noperate the inn here.",
        ["T41"] = "My father and I used to stay at\nthis place while we traveled...\nthis is where he said that he was\ngoing to go after Promeus--\njust before he vanished.",
        ["T42"] = "This area used to be lively and\nwarm when I was a child.\nOf course, I always wished that\nyou would come and take me away\nsome day...my best friend -- the\nPrince of Verdite. I was jealous,\nI wanted to be a princess!",
        ["T43"] = "I know you'll have to leave soon\nas well...it's been so long since\nanything I remember of my\nchildhood has been so real as to\nstand right before me--speekirg:\nto me. Everything is different\nnow...please be careful.",
        ["T44"] = "You know...on one of our walks\nAlexander gave me a ring. He\nsaid he found it at the Dragon\nSpring.",
        ["T45"] = "I was so happy to receive that\nring -- I looked up to him so\nmuch. He was so kind and\nfriendly. He put a charm on it\nfor me and said....",
        ["T46"] = "\"If you ever want to see me, wear\nthis ring and come to the Dragon\nspring. I will be there.\" But\nAlexander is dead now. I can\nnever see him again....",
        ["T47"] = "Oh well, thanks for stopping by\nanyway, take care...if we get\nthrough this someday, I hope I'll\nbe seeing you -- maybe at the\ncastle again, like in the good\nold days...maybe we could\neven.... Well anyway, thanks.",
        ["T48"] = "Please be careful, my old friend.",
        ["T52"] = "Welcome weary traveler! You must\nhave come far to reach such a\ndesolate place. Come, have a\nlook at some of the rare\ntreasures and collections I have\nacquired from far off lands and\ndistant places.",
        ["T53"] = "No doubt you will be needing\nprovisions before you go. Jens\nand I are the only ones living in\nthis cave now; the others have\nall either fled or been killed.",
        ["T54"] = "Jens is a skilled blacksmith,\nbut he only makes armor\nnowadays. He used to be master\nat creating weapons too--uratil\nRojee was killed. The last weapon\nhe made was by far his greatest\nand most powerful weapon!",
        ["T55"] = "He must be thinking about that\nagain...he always closes his door\nwhen he's thinking of his son's\ndeath...\"Cursed weapon!\" he\nsays...\"If only Rojee hadn't found\nit...\" He's been in there for a\nwhile this time...poor guy.",
        ["T56"] = "There are some places inside\nthe cave filled with slimy\nthings. The area used to be a\ncemetery--but I wouldn't go\nthere if I were you!",
        ["T57"] = "Jens buried his son with that\n\"cursed weapon\" in that old\ncemetery.",
        ["T58"] = "The weapon was called Elchris\nBow. Man, what a weapon! The\nonly downfall is that it sucks\nthe energy out of its user....",
        ["T59"] = "Apparently Rojee wasn't skilled\nenough to use it.",
        ["T60"] = "I could have sold that bow for a\nking's ransom!\n--It's a shame about Rojee.",
        ["T61"] = "Garan Lizards were spotted inside\nthe cave the other day. I guess\nit won't be long now before this\ncave is totally empty...our days\nhere are numbered.",
        ["T62"] = "Those Garan Lizards shouldn't\nhave been there!",
        ["T63"] = "We're going to have to hide if we\nwant to stay alive -- if they\nfind us, we're finished!",
        ["T64"] = "I can't do any business in this\ncountry. I wish I could sell the\nweapon Jens made!",
        ["T65"] = "If only the bow had been made\nfrom Promeus, it would have been\nperfect!",
        ["T66"] = "Jens is among the greatest\nblacksmiths ever to live. We\nhave an ancestor, Warren, who had\nsuch a talent, but Jens may even\nsurpass Warren's expertise and\nprecision.",
        ["T67"] = "I really could sell Jens's Bow\nfor a fortune!",
        ["T68"] = "We certainly could use some\nPromeus. But alas, nothing like\nthat has ever turned up around\nhere.",
        ["T69"] = "Unfortunatley, Promeus ore is\nfound only in the land of Garan.\nWe know it can't be found in\nthis area.",
        ["T70"] = "I once lived in the land of Garan\nand hunted the ore for myself.\nMany people got killed because of\nthe Garan Lizards. So obsessed\nwith their quest, they were\nwilling to die for a mere\nfarthing of Promeus.",
        ["T71"] = "Of course, we have no idea if\nPromeus is still in Garan at all.",
        ["T72"] = "In fact, I am beginning to wonder\nif there is even such a thing as\nPromeus....",
        ["T73"] = "I remember Jens made an\nawesome sword once, long ago.\nIt was supposed be used by the\ngreat Commander, David Silviera\nto defeat this infectious evil in\nour land once and for all!",
        ["T74"] = "He named the sword Capricorn...I\nwonder what happened to it. No\nhuman could have used that sword,\nit must still be lying around\nsomewhere -- unused since the\ntime of Silviera's disappearance.\nWhat a waste!",
        ["T75"] = "The Elves began to worship Seath\nand made temples in his honor. I\njust can't understand it, why\nwould they....",
        ["T76"] = "Why are you staring at me like\nthat? Oh...did I say that out\nloud -- sorry, Elves have always\nbeen a bit of an enigma to me.",
        ["T77"] = "I wanted to tell you something...\nOh ya' -- If you have to go near\nthe castle, make sure to take a\nweapon that shines the power of\nlight with you. The monsters in\nthat area hate the light.",
        ["T78"] = "I know there used to be a sword\nwith that power...it was called\nthe Moleonlight Sword. Now that\nwas a powerful weapon!\nUnfortunately, it was broken by\nthe powers of evil a little over\nten years ago.",
        ["T79"] = "There is supposedly one other\nsword with that power. It's\ncalled the Triple Fang. I've only\nheard legend of that sword\nthough, I have never actually\nseen it. Leon must have brought\nit out of the castle if it exists.",
        ["T80"] = "There are other weapons, of\ncourse, but they're not very\neffective. When it comes to the\nknowledge of weaponry, no one\nknows more than I do.",
        ["T84"] = "I don't feel like making\nanything. Please leave me alone.",
        ["T85"] = "Look, my son died because of that\nbedamned weapon I made! If you\nwant it, take it...let the curse\nbe on your shoulders. I buried it\nwith him and threw away the key.\nI must warn you though, no good\ncan come of that insidious bow.",
        ["T86"] = "I don't feel like making\nanything.",
        ["T87"] = "You have a rare and unusual\nobject. I don't make weapons, but\nI could make protective gear for\nyou...",
        ["T88"] = "Wait here for a while.....\nI can't make it that quick.",
        ["T89"] = "You must take good care of it --\nnot many people can obtain\nsomething like this...others may\nwish it for their own (if ya'\ncatch my drift).",
        ["T90"] = "If you ever get hold of Promeus,\nplease bring it to me.",
        ["T91"] = "The walls in this area are\nreddish because of oxidation. You\nwon't find Promeus here.",
        ["T92"] = "If you have no business, don't\nhang around.",
        ["T93"] = "Whoa! How did you find it?\nOkay...well a deal's a deal, I'll\nmake it for you since I did\npromise.",
        ["T94"] = "Don't rush me....",
        ["T95"] = "So, what are you going to do with\nit? Of course, you can sell it or\ndo whatever you please with it, I\nwas just curious. It does seems\nfitting for you to have it\nthough...well, good luck to you\nsir.",
        ["T96"] = "I didn't know that Promeus was\nstill found in this country.",
        ["T97"] = "You may encounter Golems\noccasionally. Shudom, Archmage\nof Earth created the Golems in\norder to search for Promeus...\nlazy bum! If the Golem discovers\nPromeus, it will turn gray and\nwill be called Promeus Golem.",
        ["T98"] = "But I don't believe there is any\nPromeus in this area.",
        ["T99"] = "What? You've found another one!?\nMan, you're really pushing this\npromise thing here...okay, okay,\nI admit I love to work with\nPromeus anyway...see you in a\nwhile.",
        ["T100"] = "It will be finished very soon. Be\npatient!",
        ["T101"] = "I haven't made anything for quite\na while. But my skills are better\nthan ever!",
        ["T102"] = "I haven't seen Gullick recently.\nI wonder how he's been.",
        ["T103"] = "The Elves may be able to utilize\ncrystals or gold, but we Dwarfs\nare the only ones who can use\nPromeus.",
        ["T104"] = "Molest of this cave has been dug by\nHell Worms.",
        ["T105"] = "I guess a lot more Promeus can be\nfound if you search hard enough\n...what's your secret?",
        ["T106"] = "If you rush me, I can't produce\nquality goods.",
        ["T107"] = "Ah...Finished! This armor is even\nbetter than Warrens! Have you\nheard of him? He was a famous\nBlacksmith long ago. Why he\ncould...oh, you've heard huh?",
        ["T108"] = "The armor made by Dwarfs is\nusually too heavy for humans,\neven those made with Promeus.\nIt's sad that their frames are so\npuny and weak.",
        ["T109"] = "That's what happened with the\nsword I made for Silviera. Once\nhe was gone, no one could use\nCapricorn. Too bad about him...he\nreally was a great warrior....",
        ["T110"] = "Bring Promeus, if you want to\nhave anything to do with me.",
        ["T111"] = "Look at me, I'm obsessed! It's\njust that as a blacksmith, I get\nreally excited about working with\nPromeus. It's so easy to shape\nand mold, yet so strong! It's\nalmost as if it was created just\nto be worked by my hands!",
        ["T112"] = "I understand you want to hurry,\nbut you need to be patient.",
        ["T113"] = "This is the best I have ever\nmade! What a masterpiece!",
        ["T114"] = "You'll end up an appetizer for\nthe Garan Lizards if you stay\nhere much longer.",
        ["T115"] = "I'm a Dwarf, we pride ourselves\non being able to locate and mine\nANY material that exists in dirt\nor rock -- yet I couldn't find\nthis...how could you possibly\nhave found it?! What, do you just\nconjure it out of thin air?!",
        ["T116"] = "I cannot be rushed. How many\ntimes do I have to tell you this?",
        ["T117"] = "I feel as though I have really\naccomplished something here. It's\nnot every day that a man can be\ngiven the chance to mold a near\nperfect material into a perfect\nwork of art! Thank you!",
        ["T118"] = "Don't waste what I've made for\nyou Molest men can only dream of\nfinding enough Promeus to mold\nsuch a masterpiece.",
        ["T119"] = "I won't do anything for anyone\nwho kills.",
        ["T120"] = "Leave here at once!",
        ["T124"] = "Hi Lyle! My you've grown since\nthe last time your father stopped\nby! What's your hurry?! Please\ndon't leave so soon! I haven't\nhad a guest here for months and\nI'd love to hear how you've been.\nI'll only charge you 150G! Okay?",
        ["T125"] = "Ed has been taking good care of\nyour mother's tomb. He's a good\nman, Lyle. He knows more about\nthat old cemetery than anyone! I\nthink he even knows of a passage\nto the back of the cemetery...\nperhaps he'll open it for you.",
        ["T126"] = "Commander Silviera used to stay\nhere in my Inn...he and his men\nwere always full of such laughter\nand high spirits! He used to tell\nhis men that if they stayed here,\nthey would dream of the future...\nI wonder if you'll have a dream!",
        ["T127"] = "I wish I could be of more help to\nyou, Lyle, I feel so useless just\nsitting here. I've owned this inn\nfor over 50 years -- you'd think\nI could offer something more than\njust pleasant conversation and a\ngood night's sleep.",
        ["T128"] = "Sorry for complaining earlier, I\nguess not just anyone can operate\nan inn. An inn has to offer a\nplace where a person can truly\nrest. A good night's sleep is the\nonly way to feel truly revital-\nized. That's my gift, sleep well.",
        ["T129"] = "So how's that little girlfriend\nof yours? I haven't teased you\nabout her in years! You two used\nto be so cute when I'd come to\nvisit the castle! What was her\nname?",
        ["T130"] = "This country is in turmoil, Lyle,\nI'm afraid that if something\nisn't done soon, your people will\nlose all hope for the future.\nPlease don't let that happen!",
        ["T131"] = "Your mother was such a beautiful\nand gentle lady. I wish I could\nhave saved her! I just had no\nidea that King Alfred was capable\nof such a thing! I know it wasn't\nreally him, but what horrid beast\ncould have done such a thing?",
        ["T132"] = "Leon told me about what happened\nto Alfred. He didn't want me to\nblame the King for what had\nhappened in this land. I know the\nking was not to be blamed, but it\nhas all been so tragic! Please\nbring peace back if you can...",
        ["T133"] = "Please, come in! You are always\nwelcome here. Does my pipe\nbother you? I took up the habit\nabout ten or fifteen years ago --\nit settles the nerves.",
        ["T134"] = "So...do you think that when you\nare king, you will come and stay\nhere again some time? It sure\nwould be nice to be able to say\nthat you stayed here! People like\nto hear things like that...an inn\nfit for a king!",
        ["T135"] = "I wish I could hear those\nsoldiers talking and laughing\nagain, it was music to my ears\nto have all my rooms filled with\nhappiness! What a horrible war\nthis has been!",
        ["T136"] = "Good to see you, Lyle, come back\nagain soon!",
        ["T140"] = "It used to be that everywhere in\nthe three kingdoms, the people\nrevered our king. But as our\npeople began to lose their lives\nand their property, they lost\nfaith in him.",
        ["T141"] = "With the situation worsening\nevery day, people have begun to\nhate the king. Word is spreading\nto the other kingdoms as our\npeople flee for their lives...no\none comes here now. It has become\na desolate and lonely place.",
        ["T142"] = "People used to believe that a new\nhero would come to rescue us --\nsomeone like Alexander or our\nformer king. We had all hoped\nSilviera was that hero.",
        ["T143"] = "But since Silviera's disappeared,\nI'm afraid that there is just no\nhope left here. The people no\nlonger await a hero...now they\nawait their own deaths. What\nmisery and treachery the king has\nbrought upon us.",
        ["T144"] = "My father had the stone statue in\nfront of the inn carved out of\nrespect and admiration for the\nking. It's been defaced now,\nmarred like our kingdom. I'm glad\nmy father isn't alive to witness\nall of this.",
        ["T145"] = "My father couldn't have lived\nknowing that the king and this\nkingdom had taken such a wicked\nturn.",
        ["T146"] = "The South River used to be\nbeautiful with clear water, but\nnow the demons have turned it\ninto a churning bed of glowing\nlava. The cave beyond that was\ndug by the Archmage, Shudom...\nstrange place that must be!",
        ["T147"] = "Shudom was called the Dark Lord\nof the Earth Spirits. He created\nbeings out of the very earth.\nIt's been quite a while since his\ndeparture, but you can still hear\nthe howling of his dark spirits\nfrom within that cave...",
        ["T148"] = "No one has ever gone to the cave\nof Shudom and returned. And no\none in his right mind would ever\ngo near it now. You scare me.\nI'm very sorry, but I'm afraid I\ncan't let you stay in the inn.",
        ["T149"] = "Your father is responsible for\nthis kingdom's undoing -- unless\nyou can do something to save it,\nyou are no better than the king\nhimself.",
        ["T150"] = "There is a building near Ralugo\nthat was erected by Harvine, the\nKing of Wind. If you go there --\nGod save your soul -- you must be\nextremely careful! There are as\nmany dangers there as around the\ncave of Shudom.",
        ["T151"] = "You're looking for four\nArchmages, right? Leon said this\nwould happen.\nI heard a while back that someone\nsaw Ungrund, the Archmage of the\nEarth, near the Lava River.",
        ["T152"] = "I've heard that the Archmages\nmade an alliance in order to\nprotect themselves from the evil\ncreatures until the Chosen One's\narrival...they went into hiding\nshortly there after and must have\nbeen waiting for YOU ever since.",
        ["T153"] = "I guess it's true, no one has\nseen the four Archmages together\nsince, and it's been ten years\nnow!",
        ["T154"] = "I used to play with King Alfred\nas a child. Your grandfather,\nHouser, was known as the Sword\nMaster and King Alfred learned\nthe art from him. He became an\nexcellent swordsman with his\nfather's help.",
        ["T155"] = "I just can't believe what has\nhappened to the king.",
        ["T156"] = "Oh, but speaking of the Sword\nMaster, there lives an old Knight\nnamed Lord Veyrac in the village\nof Cason. How about paying him a\nvisit? He's a fine swordsman, and\na friend of your grandfather's.\nMaybe he could help you.",
        ["T157"] = "I firmly believe you will become\nan excellent king some day...\nplease make it soon!",
        ["T172"] = "I was told that because you are\nthe king's son, you wouldn't be\nof any use, but I don't care if\nyou are the prince to this God\nforsaken kingdom.",
        ["T173"] = "My son desperately needs the red\nmedicinal herb, and I know you\ncan get it! Please help us...\nwe're desperate!",
        ["T174"] = "He lost consciousness while\nclutching the toy dagger his\nfather made for him. If the fever\nremains high like this... ...\nJust PLEASE...help him!",
        ["T175"] = "With this medicine, my son will\ncertainly recover! I can see that\nI was wrong to listen to others\nabout you. Thank you, thank you\nvery much!",
        ["T176"] = "I would like to express my\ndeepest gratitude. As you can\nsee, Airon has completely\nrecovered. Please drop in and see\nus if you're ever in the\nneighborhood.",
        ["T177"] = "Take care of yourself, someday I\njust know you'll be able to give\nthe hope back to your people that\nyour father took away.",
        ["T178"] = "I'm not going to let him out of\nmy sight! Last time he almost\ncaught his death, I don't want\nhim catching some strange disease\nagain.",
        ["T179"] = "Children his age are so curious\nand adventurous, I guess I'm just\nworried that he'll sneak outside\nwhen my back is turned. I don't\nknow what I'd ever do without\nhim...",
        ["T180"] = "Since the death of my husband, my\nson has been my only reason for\nliving. I'm so glad he has\nrecovered.",
        ["T181"] = "I would very much like my son to\ngrow up to be like you.",
        ["T182"] = "Please...he's ill again...I fear\nthat he must have stepped in the\npath of the poisonous wind. I had\nwarned him many times not to go\nnear it, but... ...\nWhat should I do? I don't\nwant to lose my son.",
        ["T183"] = "\"Lyle, the crown of Ichrius is\nin the far land of Garan. It\nwon't be long before the seal is\nbroken.\"... ...\nUh...wha'...wh--where am I!?\nWhat's going on?? Mommy, what\nhappened?",
        ["T184"] = "I was playing outside and all the\nsudden I couldn't breath...I had\na dream that I was dying and then\na man came and said everything\nwas gonna' be okay...then he said\nsomething about...Ik...Ich...some\ncrown thing. Now I'm here....",
        ["T185"] = "Thank you again, Prince Lyle, I\ndon't know how I'll ever repay\nyou! Since I can't keep him out\nof trouble, I'll try to convince\nhim that he should stay out of\ndangerous places...Thank You!",
        ["T188"] = "Underneath everything the hidden\ntruth is contained -- but it is\nnot obvious. It is imperative to\nknow the truth and pursue the\npath which you have set forth.",
        ["T189"] = "I'm trying to find the meaning of\ntruth to make it a part of me.\nWhat do you call a cross between\na banana and a gymnast? A banana\nsplit! Ha-ha-ha-ha-ha-ha!! Tee\nhee? Ahem...Trivial matters in\nthe kingdom don't interest me.",
        ["T190"] = "If you obtain the knowledge of\nyour own fate and understand its\nmeaning, soon your appointed\nfuture will become clear to you.\nUntil then, wear lots of\nsynthetic leather and learn to\ndance the polka.",
        ["T191"] = "You will be defeated by your fate\n-- unless you find the path\nbefore the sorrow comes. Orladin\nwas a good example....",
        ["T192"] = "All truth shall never be one\ntogether. Each man's own truth\nmust be his guide while searching\nfor deeper truth in the universe.\nWhen you have found the path to\ntrue knowledge, come back and ask\nme anything you like.",
        ["T204"] = "I see that you are now\nready to receive my gift.\nLet the very winds of the\nsky be at your command!",
        ["T205"] = "You now have control of\ngreat power. Go now into\nVerdite and reclaim your\nkingdom!",
        ["T212"] = "Oh most blessed of days! It is\nyou!! Alexander told us of your\nimminent arrival 10 years ago...\nso this has come to pass that\nyou have grown into a man.",
        ["T213"] = "My gift is of Fire...allow\nthe powers of fire to burn\nthe flame of courage deep\nin your heart, Prince Lyle.",
        ["T220"] = "This is indeed a grand occasion!\nAlexander foretold your arrival.\nReceive now the power of Earth.\nLong live the new King!",
        ["T221"] = "Soon you will come to know the\ntrue power of the gift which\nAlexander has bequeathed.\nHail to thee, Prince of Light.",
        ["T228"] = "I am the caretaker of this lake.\nNo one has crossed here for over\nten years...not since the solid\nbridge was destroyed. There is a\nwater bridge that was erected by\nOrladin a long time ago...",
        ["T229"] = "But no one can cross the water\nbridge without the Aquarian Boots\n-- and thus far, no one has been\nworthy of this gift....\nTen years ago, I was forced to\ndestroy the ancient stone bridges\nthat spanned our beautiful lake.",
        ["T230"] = "I did it to prevent any demons\nfrom crossing to this side. I can\nchange the location of the water\nbridge by turning the dial in\nthis room, so he who crosses by\nOrladin's permission will have no\nneed of stone bridges anyway.",
        ["T231"] = "The path you have taken is called\nthe Path of Poison. The path was\nmade by Orladin -- I believe the\nBoots are still there...no one\nwho has gone this way has ever\nreturned.",
        ["T232"] = "I will open the gate if you will\ngive me the medicinal herb. Once\ninside you can change the\nlocation of the bridge for\nyourself.",
        ["T233"] = "''''''''''''''''''''''''''''''''",
        ["T234"] = "I will open the gate now.",
        ["T235"] = "The next is Blood Stone. For\nthis, I would be glad to open the\ngate for you again.",
        ["T236"] = "''''''''''''''''''''''''''''''''",
        ["T237"] = "Go ahead, please.",
        ["T238"] = "Now the Moleon Stone...will you\npart with this precious stone?\nOnly then will I open the gate to\nyou.",
        ["T239"] = "''''''''''''''''''''''''''''''''",
        ["T240"] = "Please come in.",
        ["T241"] = "Higher and higher becomes the\nprice...I will open you the gate\nfor the fabled fruit of the\nDragon King Plant...will you\ncontinue onward?",
        ["T242"] = "''''''''''''''''''''''''''''",
        ["T243"] = "You are indeed worthy, as\nAlexander had said, please enter.",
        ["T244"] = "How much Alexander has been\nlooking forward to this day! I\nnow bestow upon you the Power\nof Water.",
        ["T245"] = "You have begun climbing the\ngreat staircase of Fate. You\ncannot come down now. Alexander\nand I will be watching over you.",
        ["T260"] = "Lyle, I must speak to you\nbefore you go to the castle.\nThat's why I used the fairy to\nplay a trick on Robert Shreve...I\nknew if I left my staff, you\nwould come.",
        ["T261"] = "King Alfred, your father, wanted\nyou to receive the three Seals of\nIchrius. He entrusted three\npeople to keep guard over the\nseals.",
        ["T262"] = "One of the seals is the Eye of\nIchrius...which my fairy cleverly\nremoved from the care of Robert.\nOnce all three seals are brought\ntogether, the key of Ichrius can\nbe made. The only person left who\ncan make the key now is Leon.",
        ["T263"] = "I now bestow upon you the Eye of\nIchrius...With it, I'll also give\nyou this map. With the power of\nthe fairy of the Woods and the\nWind, you will be guided to the\nright path.",
        ["T264"] = "The Seals of Ichrius will lead to\nthe golden fountain which was\nbuilt by Ichrius himself.",
        ["T265"] = "Lyle, obtain the three seals\nquickly, time is running out for\nall of us. The power of Ichrius\nwill be necessary if you are to\nsucceed.",
        ["T266"] = "Turcotte Ichrius is the ancestor\nof the High Elf. He has acquired\nthe truth and obtained power.\nKing Alfred inherited the blood,\nthough small. He was thus\nempowered...as are you.",
        ["T267"] = "In the past, no one obtained the\npower outside Ichrius except\nOrladin, the Great Archmage. But\nin order for you to fulfill your\ndestiny, you must obtain that\npower.",
        ["T268"] = "The seal is nearly weak enough\nfor King Alfred to break...if the\nseal is broken prematurely, there\nis no hope for this kingdom...\nnothing will stop his reign of\nterror.",
        ["T269"] = "Deep in the woods, you will find\nthe Palace of Wind which was\nbuilt by King Harvine. Seven or\neight years ago, Calmathar, the\nArchmage of the Wind, headed\ntoward there. I'm sure she must\nstill be there.",
        ["T270"] = "One thing you should know though\nis that you cannot enter the Wind\nPalace unless you possess the\npower of wind. And even then, you\nwill find the palace full of evil\nspirits left by Harvine. People\nseldom return from there.",
        ["T271"] = "King Harvine left his guard, John\nCreel, to guard the entrance.\nJohn has been faithful to his\ntask now for over 300 years!",
        ["T272"] = "When Harvine died, I hear that\nthe palace was covered with a\nthick, mystical darkness. It's\nbeen that way ever since.",
        ["T273"] = "Time is short. Even as we speak,\nthe seal of the castle is\nweakening. You must hurry to\ndiscover the remaining Seals of\nIchrius.",
        ["T274"] = "Make Haste! Time is short.",
        ["T275"] = "For the sake of all of elfhood\n(and humanity), take the three\nseals to Leon immediately!\nThere's not much time left for\nany of us!",
        ["T276"] = "Send my greetings to Leon.",
        ["T277"] = "The time to fulfill our destiny\nis upon us, Prince Lyle. Please\naccept the apologies of my\npeople. If it weren't for our\nblindness, I feel it wouldn't\nhave come to this...",
        ["T278"] = "But, you know what they say...\nhindsight is 20/20 -- the past is\nbehind us, Lyle, we wish not to\nrepeat it....Now please, make\nhaste!",
        ["T292"] = "So, the time has finally come to\ngo to the castle....You must be\nvery careful, your father will be\nwaiting...and boy is he gonna' be\nmad! --You aren't just late for\ndinner this time! -- Heh heh.",
        ["T293"] = "I don't know if I mentioned this\nbefore, but the defense wall of\nSilviera on the north side was\nbuilt by the garrison about six\nyears ago. We can be safe today\nthanks to their work.",
        ["T294"] = "The other side of the wall is\ncalled the old battlefield (not\nnearly as old as I am though).\nThat's where the garrison used to\nfight off the invading monsters.\nHardly a garrison at all, I guess\n...they weren't really trained.",
        ["T295"] = "They were just a bunch of ragtag\nsoldiers on some idealistic\ncrusade -- trying desperately to\nsave their lands and homes.\nI don't want to think about it\nanymore. I've been living here\nfor 150 years now -- or is it 90?",
        ["T296"] = "Heck, I can't remember. Anyway,\nI've never had a bit of trouble\nin this house -- I used to be a\nbaker at the castle, you know...\nbut I never did find that recipe\nI was looking for...it was...\nrecipe...zzz...zzz...zzz... PIES!",
        ["T297"] = "Oh, sorry...yes, it was a\ndevastating and terrible war. A\nlot of good men were lost.\nWhen the wall was finally\ncompleted, the invading evil\ncreatures finally left. But the\nprice we paid was high.",
        ["T298"] = "The survivors included but a\nhandful of soldiers and Silviera\nhimself, the most revered warrior\nand bravest Commander to grace\nthe battlefield.",
        ["T299"] = "Commander Silviera truly was a\nsplendid warrior as you can\nsurmise from the stone statue\nover there. But even he was\ndevastated by the war.",
        ["T300"] = "Weary from months of fighting the\nendless barrage of evil, and\nbroken by the loss of so many of\nhis own men in the endless\nbattles, Commander Silviera\nheaded for the castle alone to\ntry to avail his lost troops.",
        ["T301"] = "We have no idea what has\nhappened to him, he just\nnever came back -- hmm,\nkind of like that pie recipe.",
        ["T302"] = "He was a brave soldier with a\nhigh sense of commitment and\nloyalty to his country....",
        ["T303"] = "There was an Archmage named\nGarnabus who joined the battle at\nthe beginning of the war. He left\ndue to some important missions\nand was escorted by some of\nSilviera's men.",
        ["T304"] = "I wonder if the \"important\nmission\" has something to do\nwith you.",
        ["T305"] = "Have you gone through the\nPath of Poison at Ralugo? If\nyou have the Silver Ring,\nyou'll have nothing to fear,\nbut it is difficult to obtain.",
        ["T306"] = "The path not only gives out\npoison but afflicts people with\nstrange illnesses. The Blood\nSucking Plant will help you\nrecover, but the plant is now\nvery rare. It grows only by the\nside of the lava beds.",
        ["T307"] = "There used to be plenty in Ralugo\na long time ago, but then those\nfolks in Cason were caught\nshipping it out of Ralugo and\nwe just haven't seen any here\nsince...",
        ["T308"] = "So what I'm saying is, watch out\nfor the poison! You're no good to\nus dead.",
        ["T309"] = "The Dwarfs used to dwell in the\neast, but most of them have fled\nnow, leaving very few behind.\nAmong those remaining are some\nof the world's best blacksmiths.",
        ["T310"] = "Those caves yonder have been dug\nby the Hell Worms. Because they\neat rocks and dirt, some of the\nHell Worms carry Verdite in their\nstomachs. Warlocks used to kill\nthem to harvest the Verdite, and\nnow the worms are almost extinct.",
        ["T311"] = "Now, people have been circulating\nthe rumor that Promeus was found\nin this area -- blind fools! From\nthe color of the rocks, you can\nsee that it could never be found\nhere. If it still exists at all,\nit will be in the land of Garan.",
        ["T312"] = "If you go there, be careful. The\nland is filled with creatures\ncalled Garan Lizards. They are\nevil and dangerous. Pray that you\nnever have to go there, but if\nyou do, be careful and good luck.",
        ["T313"] = "Please rescue this kingdom.",
        ["T314"] = "Near the Field of Ice is a path\ncalled the Path of Death. Inside,\nit's said you'll find the key of\nthe Holy King which opens the\ntreasure box of the royal family.\nNever been there myself, probably\nwhy I'm still alive -- heh heh..",
        ["T315"] = "You're growing into quite a young\nman, Prince Austin Lyle Forester.\nIt brings me joy to see how you\nhave grown....Why I remember when\nyou were just knee high to a\nbuffalo! There was this cute\nlittle missy, Lyn, at the castle.",
        ["T316"] = "You convinced her that someday\nthe two of you would get married\n-- just before you convinced her\nthat dog biscuits were really\ncookies -- heh-heh-heh-heh --\nwheeze -- cough-cough...yep,\nthose were the good old days.",
        ["T317"] = "Please don't forget about me when\nyou are king. I may be old, but\nI'm still sharp as a moldy ol'\nwheel of chedder...mmm...\ncheese...",
        ["T324"] = "''''''''''''''''''''''",
        ["T325"] = "Thanks, mister! For a while, I\nwas scared I was gonna' die!\nHere, take this...I found it on\none of my treasure hunts...\nIt's my best treasure, but I want\nyou to have it. Go on, take it!",
        ["T326"] = "You like my dagger? I'd give\nthis to you too, but I can't.\nMy Daddy made it before he\nwent away, and I'm never\ngonna' let it go.",
        ["T327"] = "Where are you going? Are you\ngonna' to take care of those bad\nmonsters before you go?",
        ["T328"] = "If I were a little bigger, I'd\nshow them a thing or two!",
        ["T329"] = "If I find anything else, I'll\nmake sure to show it to\nyou, you're pretty cool...",
        ["T330"] = "There's a secret door at the Path\nof Poison. I was there once, but\nI got scared and left. There was\na fire breathing dragon there!\nNo, I didn't see it, but it did\nbreath fire...I think it was a\ndragon....",
        ["T331"] = "I'm thinking about exploring\nthere again.",
        ["T332"] = "I found a room full of treasure\nboxes too, but I couldn't open\nany of them 'cause they were\nall locked.",
        ["T333"] = "I'm sure there's something\nwonderful in them.",
        ["T334"] = "I'm sure there's something\nwonderful in them.",
        ["T335"] = "I'm sure there's something\nwonderful in them.",
        ["T336"] = "Geez! Persistent aren't you?\nOkay, here...I found this neat\nrock by the lava...you can have\nit, but you have to promise not\nto tell my Molem.",
        ["T337"] = "Treasure hunting is sure fun!\nMaybe I'll be a pirate someday!",
        ["T340"] = "My name is Marcus. You're\nlooking for weapons of Promeus,\naren't you? Well, if you find\nany, don't expect to get away\nwith them. There's no way to\nescape from this country. I came\nhere to find Promeus too.",
        ["T341"] = "Now I just want to finish off as\nmany demons as I can before I die\nhere. You should definitely have\na Promeus weapon if you plan to\nsurvive. I have one! I discovered\nmine way up north, but I hear\nthere are some around here too.",
        ["T342"] = "I've also heard that there is a\nDwarf living here who can make\na weapon out of raw Promeus ore.\nI wonder how I can find him.",
        ["T343"] = "Have you heard of Garan Lizards\nyet? Evil creatures! They dwell\nin the north and prey on the\nDwarfs. There may be some\naround here.",
        ["T344"] = "If you ever come across the\nGaran Lizards, pray that you\ndie quickly.",
        ["T345"] = "I suppose the weapon-making\nDwarfs may have been eaten\nby the Lizards...I hope not.",
        ["T346"] = "There are lots of Hell Worms\naround here too. They consume\nlarge amounts of dirt, so they\ncarry lots of stuff in their\nstomachs.",
        ["T347"] = "If you ever see one, keep as far\naway from their jaws as possible!\nThe Hell Worms can bite off and\nchew up rocks like they were\nmarshmallows. Just think of what\nthey could do to you!",
        ["T348"] = "I hope to see you again.",
        ["T349"] = "I wonder if there is any Promeus\nhere.",
        ["T356"] = "Our neighbor, Airon, has been ill\nfor a long time. He needs a rare\nmedicinal herb...you've got to do\nsomething to help him. After all,\nyou belong to a royal family,\nsurely you must have access to\nthe medication he needs....",
        ["T357"] = "If Airon is going to get better,\nhe needs the red medicinal herb\nfrom the Blood Sucking Plant.\nI'm told that the plant is thusly\nnamed because of it's blood red\ncolor...or maybe the plant really\ndoes suck blood. I couldn't say!",
        ["T358"] = "Anyway, I'm very busy, so if\nyou're not going to help, please\ngo away and quit dashing the few\nremaining hopes your people have.",
        ["T359"] = "I'm amazed you've actually\nfound the Blood Sucking Plant!\nNot all royal family members\nare bad after all!",
        ["T360"] = "I don't know if you've been there\nor not, but the Palace of Wind\nlies to the north. The palace is\nmagnificent and befitting of the\nking who ruled the three\nkingdoms long ago.",
        ["T361"] = "You've seen the caves beyond\nthe lava river? Well, they say an\nArchmage named Shudom used to\nlive there. At great personal\nrisk, I put a bridge on the lava\nriver for you.",
        ["T362"] = "Not that I need to be compensated\nor anything (gold would be fine).\nYou may find something useful in\nShudom's cave that will help you\non your quest. But be careful,\nstrange sounds come from within\nthat cave!",
        ["T363"] = "Did you know that I used to be a\nsoldier? I fought against those\nmonsters with Commander Silviera.\nI fled though. I had to run away\nafter I took a crossbow bolt in\nthe shoulder -- I couldn't have\ndone any good to anyone dead!",
        ["T364"] = "I'm waiting for the Commander\nto return so that I can prove\nmyself to him. Mleanwhile I'm\ntraining myself to be the best\nsoldier under his command.",
        ["T365"] = "I'm eating well to regain\nstrength and training hard in the\nart of swordplay. I hope to be of\nuse to the Commander when he gets\nback. He really does deserve our\nrespect and admiration. I wonder\nwhen the Commander will return...",
        ["T366"] = "Something may be hidden in the\nwall. Let's have a closer look...\nThere are many traps in the maze.\nSome of them can be disabled, so\nlong as you find them.",
        ["T367"] = "For your own good, make sure you\nsearch for them carefully! Man,\nwhat an adventure! This is really\nliving. I believe that you have\nto live on the edge to enjoy\nlife to its fullest. That's my\nnew philosophy!",
        ["T368"] = "I'll tell you something important\nbut it's a secret...You've heard\nof the sword \"Capricorn\" right...\nthe sword the Dwarfs gave to\nCommander Silviera?!",
        ["T369"] = "Well, I have hidden it in the\nback of the barracks. It's so\nheavy no one can use it. I'm\nthe only one who can even lift\nit. How do you get to it? That's\nthe spirit! You should have no\nproblem getting to the barracks.",
        ["T370"] = "Once you get there, then the real\ntest begins. There will be many\nlocked doors standing in your\nway. I do have a key buried in\nthe backyard that you can take\nwith you, but I don't know how\nuseful just one key will be.",
        ["T371"] = "There are, of course, weapons in\nthere other than Capricorn. But I\ncouldn't say what kind. I've\nnever gone in -- mostly out of\nrespect for Silviera. Lots of\nguys have, but none of them have\nmade it to Capricorn yet.",
        ["T372"] = "I wish our Commander would\nhurry up and return!",
        ["T373"] = "If you ever become king, I hope\nyou'll remember me. I sure wish\nyou could employ me as one of\nyour warriors, I really like you.",
        ["T374"] = "Really!? Don't forget now, you\npromised! Thank you!!",
        ["T388"] = "Sal hasn't come back from the\ncastle. He was serving there as\na member of the king's Guard\nbefore the darkness came, but\nthen the king changed, Sal was\nfrightened for his life.",
        ["T389"] = "One day he snuck out of the\ncastle...He had only returned to\nlook for his friend Endt, but now\nI fear I'll never see him again.\nHe left saying, \"You have no\nneed to worry.\"",
        ["T390"] = "How could Alexander have sealed\nthe whole castle? Didn't he think\nabout the others he would trap in\nthere with only the King's wrath\nas their reward? I hate him for\nwhat he's done to us.",
        ["T391"] = "If you're going to the castle.\nI've hidden a key that you may\nneed. Sal asked me to keep it\nsafe, so I hid it in the cemetery.",
        ["T392"] = "Please rescue Sal.",
        ["T393"] = "Take good care of yourself.",
        ["T394"] = "Was Sal okay?\nI'm so glad I've waited.",
        ["T395"] = "\"No need to worry,\"\nhe said -- ya' right!",
        ["T396"] = "No matter now, I'll forget all\nabout it when I see Sal's smiling\nface again!",
        ["T397"] = "I did like he told me and hid the\nkey...",
        ["T398"] = "I'm so glad he's okay!",
        ["T404"] = "I don't believe we've met, yet\nyou look so familiar. Who are\nyou, if I may ask? Oh! That's why\nI thought I'd seen you! Have you\nmet my sister, Priscilla? I was\non my way back home to her.\nWere you able to comfort her?",
        ["T405"] = "Have you really come all this way\nto help your people? If you're\ntelling the truth, then you're not\nat all like your father. Please\ntake this...If you're really here\nto help, find Lord Veyrac and\nheal him with this needle.",
        ["T406"] = "I fear I won't make it all the\nway back before one of those\ndemons gets me...Poor Priscilla,\nI hope I can make it back home\nto her, she's so innocent and\nhelpless. Anyway, please go. Take\ngood care, my prince.",
        ["T407"] = "Lord Veyrac has done so much\nfor us. Thank you so much for\nyour help...I think he's going\nto be okay now.",
        ["T408"] = "I wish peace would return to our\nvillage soon!",
        ["T409"] = "You really are here to help us!\nThank you for saving Lord\nVeyrac, I really appreciate what\nyou've done! Lord Veyrac is all\nbetter now, and the evil\ncreatures in this area are gone\ntoo! You have given us hope.",
        ["T410"] = "But what of the other villagers..\nIt's been very desolate here.\nSince the horrific incident 10\nyears ago, nothing but tragedy\nhas taken place. So much\npain...perhaps you will give them\nhope too.",
        ["T411"] = "I wish we could have peace soon!",
        ["T412"] = "The demons came back just after\nyou left. Lord Veyrac...he was\nonly trying to protect my sister\nand me...but there were too\nmany...they...he...Lord Veyrac is\ndead! We are the only ones left\nin this village now.",
        ["T413"] = "I just want my sister Priscilla\nto be happy again.",
        ["T420"] = "How did you get here? Toni went\nover to the river, but she hasn't\ncome back yet. There are\nmonsters everywhere! Toni said\nto wait here, but I'm scared! I\ncan't even go outside of this\narea...all I can do is wait.",
        ["T421"] = "Tending my parents' garden helps\nme forget...but then I remember\nthat they're never coming home\nagain. I wish Lord Veyrac was\nhere. He was a great swordsman\nfrom the north until the bad guys\nturned him into stone.",
        ["T422"] = "My sister went to find a magic\nneedle. She said that if she\ncould find it, it would cure Lord\nVeyrac. She's been gone for so\nlong though...I'm scared that\nshe's not going to come back\neither.",
        ["T423"] = "Lord Veyrac was nice, and boy was\nhe strong! He fought off the\nmonsters for a long time before\nthey got the best of him. I wish\nToni would hurry back! I hope\nshe was able to find that needle.",
        ["T424"] = "Do you think Toni's okay?",
        ["T425"] = "I wish these scary things would\ngo away!",
        ["T426"] = "Thank you! Thank you for helping\nLord Veyrac! Did you see my\nsister? Do you think she'll be\nback soon?",
        ["T427"] = "A while back, Lord Veyrac chased\noff the scary monsters and things\nwere a little better for a while.\nBut my sister and I were still\nsad...it's very lonely here with-\nout anyone else in the village.",
        ["T428"] = "My sister said that the people\nwould come back again though,\nand she told me that I'd be able\nto play with other kids again\nsoon!",
        ["T429"] = "I wish they'd all hurry up and\ncome back! Are you going to stay\nwith us? We're all alone here\nnow...you know about what\nhappened to Lord Veyrac right? I\nwas just going over to where he\nwas.",
        ["T430"] = "I was so happy to see him again\n...but the scary monster came\nfrom nowhere! I almost got\ncaught. Lord Veyrac cut him\noff so I could get away...\nhe was only trying to help\n...but....",
        ["T431"] = "'''''''''''''''''''''''''''''''''",
        ["T436"] = "My name is Marilyn. I've seen you\nbefore, haven't I....You were\nhere with Leon, right?",
        ["T437"] = "I came here in search of my son,\nbut now I'm stuck here! I can't\nmove forward because of these\nrotten monsters, and I can't go\nback -- I'd be abandoning my son!",
        ["T438"] = "Please help me, my son is in\ndanger. Could you get this charm\nto him? He needs it if he is ever\ngoing to be free again.",
        ["T439"] = "I often have nightmares about my\nson being immobilized and in\nagony at the hand of all this\nwickedness. If you can get the\ncharm to him, he'll finally be\nokay again...please....",
        ["T440"] = "Thanks to you, my son has finally\nbeen set free!\nHere, take this map...I don't\nneed it anymore now that he's\nsafe! I'll pray for your safety,\nLyle -- and your victory too!",
        ["T441"] = "I have a friend named James\nSeward MoCain V who is waiting\nfor Commander Silviera to return.\nIf you ever happen to see him,\nplease tell him that my son has\nfinished his task.",
        ["T442"] = "I'd like to return to my house...\nI had a beautiful view of the\nocean from there. It was just\nmagnificent.",
        ["T443"] = "About the time that the King\nsuddenly changed and the demons\nbegan to appear, my home town\nwas covered with a deep snow.",
        ["T444"] = "The beach began to drop and shift\nand an ugly cliff replaced our\nbeautiful beach.",
        ["T445"] = "I was operating an inn at that\ntime. Many people used to come to\nvisit there. The scenery was\ngorgeous -- we were all so very\nproud of our beautiful country.",
        ["T446"] = "On a clear day you could see the\nisland of Mlelanat. You couldn't\ndescribe the beauty with words.\nSince that day, the sky has been\nnothing but dark, gray, and\ngloomy...I wish the beauty would\nreturn.",
        ["T447"] = "I used to play on the beach as a\nchild. I'd find things floating\nin the water from far off lands.\nIt was like a dream.",
        ["T448"] = "I'm sorry to bore you with an old\nwoman's memories. But I feel\nlike you're a part of my family.\nPlease come again soon....\nTake care of yourself.",
        ["T449"] = "Have you met Lyn? She's such a\nnice child. She and her father\nused to come and stay at our\nplace while they were traveling.",
        ["T450"] = "Shortly before the king changed,\nLyn's father took off looking for\nPromeus. To my knowledge, he\nstill hasn't returned. Poor Lyn.",
        ["T451"] = "At the east side of our inn was a\ncliff. The other side was called\nthe land of Garan. I have never\nbeen there, but Lyn's father\nheard that there was Promeus\nthere.",
        ["T452"] = "She was waiting at our place for\na while, but on the day of the\ngreat seal, with all the\ncommotion and confusion, she\ndisappeared.",
        ["T453"] = "I haven't seen her since then. I\ndo hope everything's all right.\nShe really was such a nice\nchild....",
        ["T454"] = "But listen to me, I'm talking\nabout the old days again!\nHope to see you again soon.",
        ["T455"] = "Is that so? Lyn...? I'm so sorry,\nLyle. I'm sorry for what has\nhappened to your father too, I\nknow all the sorrow and problems\nbegan when he changed.",
        ["T456"] = "That must be very difficult for\nyou. And the people all blame\nyou, don't they? Well, don't\nworry, I won't blame you...and\nI'm sure Lyn didn't either!",
        ["T457"] = "I have the feeling that you've\nbeen empowered to grant the\nwishes of the people...especially\nthe wish of Lyn. I hope you'll\ndo your best.",
        ["T458"] = "One of these days, peace will\nreturn to the country and you\nwill reign as king. I'd like to\ntell the people about you when\nthey return.",
        ["T468"] = "Why would you come to such a\ndangerous place on purpose? Go\nhome! Don't you know that the\nmonsters are on the prowl again?\nWhat can you hope to accomplish\nhere other than losing your own\nlife?",
        ["T469"] = "If you've been lucky enough not\nto notice, there are hordes of\nskeletons everywhere here. If you\never get caught having to fight\nthem, use the Molerning Star.",
        ["T470"] = "The ordinary swords just won't\ndo, your sword would be best used\nagainst the Grave Potts.",
        ["T471"] = "These dead bodies were the\nvictims of the evil creatures.\nLooks like they've been around\nfor a while, eh? I have trouble\nkeeping up sometimes.",
        ["T472"] = "I promised Commander Silviera\nthat I would honor the dead. So\nI'm digging graves for all of\nthem. Fallen men with families\n...what a shame; at least I can\ngive them a decent burial.",
        ["T473"] = "I do get a few items from the\ndead bodies once in a while. They\nhave no need for any of these\nitems now.",
        ["T474"] = "I have a hobby of collecting the\nitems that were excavated. Why\ndon't you drop by sometime?\nMaybe I have something you could\nuse.",
        ["T475"] = "I hear you're planning to go to\nthe castle. In that case, I\nsuggest you stop at your mother's\ntomb and pray for your soul's\nsafe passage -- going to that\ncastle is suicide!",
        ["T476"] = "I've heard of your works in this\nmiserable, beast infested\nkingdom...ya', people like you\ncome along occasionally --\npeddling hope for a better\nfuture. I hope you can bring\npeace to this place...",
        ["T477"] = "Maybe you can manage to stay\nalive long enough to do some\ngood. That's been the problem\nwith the others, they either\ndisappear or die. Please be\ncareful...don't get yourself\nkilled too.",
        ["T478"] = "I've dug hundreds of graves, I\ndon't want to have to dig one for\nyou...I hope I don't have to dig\none for Commander Silviera\neither.",
        ["T479"] = "Here's some free advise from a\nguy who's been around. If you\ndon't have one already, get a\nhold of a Silver Ring. There are\nmany creatures here that carry\npoison -- so if you want to stay\nalive, you'll wear a Silver Ring.",
        ["T480"] = "Either that, or get used to\ncarrying tons of the Antidote\nPlant with you.",
        ["T481"] = "My collections are all very\nexpensive, but if you see\nanything you like, bring it over\nhere. I'll make you a deal.\nThe very best items usually find\ntheir way to my collection.",
        ["T482"] = "For example, I have a staff\ncalled the Flame Rod -- very rare\nand powerful. There is also a\ntwin staff called the Silence\nRod. Together, the two staffs\nmake up an even more powerful\npair.",
        ["T483"] = "I'm still looking for the Silence\nRod, so if you ever find it,\nbring it here and I'll pay you\nhandsomely for it!\nMy collection is the only\npleasure I have in this miserable\nlife.",
        ["T484"] = "My sources tell me that the\nVolguard is at Lake Noel, and\nDragon Head is in the village of\nCason. I guess I'd believe it...\nmy sources haven't been wrong\nyet!",
        ["T485"] = "I also know that the Aquarian\nBoots can be found at the Path of\nPoison, but I'm finding out that\nit's very difficult to get them.\nI wish I could get a hold of\nthose!",
        ["T486"] = "I hear the descendants of the\nGarans are the Garan Tess. I\nwonder if that's true....\nThe Garan Tess are as dumb as a\npile of rocks, yet the 1st Garan\npeople were highly intelligent. I\nwonder what happened.",
        ["T487"] = "Commander Silviera told me that\nthe Garan people didn't do very\nwell acquiring magic. They\npreferred combat with swords\n(they lost and perished).",
        ["T488"] = "The real magic, of course, is to\nmake the most use of the power\ninherent to various materials.\nEven for sword play, magic plays\nan important role.",
        ["T489"] = "The weapon of the Garan was\ncalled Groundal. Groundal is\nbeyond description...how I would\nlove to see it just once!\nBut alas, I am doomed to bury all\nthat they have killed. Oh the\ntedium and horror of my task!",
        ["T500"] = "Good to see you, Prince Lyle!\nI...I've been waiting for you to\ngive you the Eye of Ichrius. The\nking gave it to me to give to\nyou...but...um...well, a fairy...\na fairy stole the Eye several\nyears back.",
        ["T501"] = "She tricked me and left me only\nwith the Staff of Varde. --Please\n...I beg of you -- HAVE MERCY!!\nShe was sent by Varde, himself,\nChief of the Woods. I've been to\nthe woods several times in vain\nto try to retrieve the eye...",
        ["T502"] = "But I could never find Varde -- I\nkept getting lost and I was\nforced to give up my search when\nthe demons came. Here, take this\n...it's the Staff of Varde.\nPlease take it and recover the\nEye of Ichrius from Varde.",
        ["T503"] = "I'm sorry I failed you, Lyle.\nI don't know what to say...I\ncertainly can't face the king\nafter all these years. I let the\nEye of Ichrius be taken from me.\nThe king will never forgive me.",
        ["T504"] = "Please Lyle, take the Eye of\nIchrius back. It was the earnest\nwish of King Alfred...I could\nnever forgive myself if you were\nnot to have it....",
        ["T505"] = "You may have heard that there are\n3 Seals of Ichrius. I was given\nthe first by King Alfred to watch\nover and keep safe until the day\nof your coming, but I have no\nidea who has been entrusted to\nsafeguard the other two Seals.",
        ["T506"] = "Soon after the king was crowned,\na messenger from the Archmage\nOrladin came to the castle.\nOrladin had died many years ago,\nthe messenger had been waiting\nfor several thousand years for\nKing Alfred to appear.",
        ["T507"] = "The messenger collapsed and\nvanished as soon as he handed the\n3 Seals of Ichrius to the Kjng.\nAlfred turned to me and said,\n\"This is not for me. This is for\nthe next king yet to be born.\"\n...That's you, Lyle.",
        ["T508"] = "He continued saying, \"It is your\nduty to take this information to\nthe next king.\"\nAnd so I have waited...for over\n20 years I have waited -- only\nto lose that which I vowed on my\nlife to protect.",
        ["T509"] = "I am a failure. I have not been\nable to reclaim the Eye, and you\nhave had to take it for yourself.\nOnly now that you have it in your\npossession can I die honorably.\nBut before you go, there are some\nthings you should know.",
        ["T510"] = "The King was very puzzled to hear\nthe name Ichrius. That name was\nnot in our history...it had never\nbeen heard before by a non-Elf.",
        ["T511"] = "Not too many people know about\nthe Archmage named Orladin who\nsent the messenger either. The\nElves may have heard about it,\nbut I know very little about him,\neven with my years of travel.\nBut soon enough, you will know.",
        ["T512"] = "I'd also like to tell you what I\nobserved at the castle after\nAlexander's death. The Moleonlight\nSword, the holy sword of your\nfather, is broken. It was buried\nwith Alexander, and the tomb was\nsecurely sealed.",
        ["T513"] = "Four Archmages, Ungrund,\nCalmathar, Zul Arifin, and\nGarnabus, formed an alliance to\nprotect themselves until your\narrival...they sealed the tomb\nwith their respective powers.",
        ["T514"] = "Only when you have mastered all\nfour principles of power can you\nbreak that seal. And unless you\nhave the Moleonlight Sword, you\ncan't break the seal to enter the\ncastle.",
        ["T515"] = "This was no accident, Lyle,\nthey don't just want any schmuk\nbreaking the seal on the castle!\nThe four Archmages stood together\non the hill of prayer...I recall\ntheir silhouette against the\nsunset...",
        ["T516"] = "They were so detached...so\nmournful...so powerful.\nThe four then went their separate\nways and have been awaiting your\narrival and the time of awakening\nof the Moleonlight Sword ever\nsince.",
        ["T517"] = "The fact that the king changed so\nsuddenly, followed by the death\nof Alexander and the loss of so\nmany people, caused the Archmages\ngreat anguish and pain..",
        ["T518"] = "They've been carrying that sorrow\nand grief for over ten years now\n...please put their pain to rest.",
        ["T519"] = "That's all I know. You are the\nonly one who can rescue our\nkingdom, Lyle...you must go now\nand prepare to meet the king.\nYou know you are our last hope.",
        ["T532"] = "Ah, you have arrived at last! My\nname is Krone Licht. Do you\nremember me? I met you once in\nthe castle a long time ago. I\nhave some important information\nfor you. Please listen carefully!",
        ["T533"] = "If you ever hope to gain enough\npower to save the kingdom, you\nmust bring together all of the\nsecret thread that Orladin has\nleft behind. He was the keeper of\nall the sacred powers of Ichrius.",
        ["T534"] = "For some unknown reason Orladin\nperished in his own Maze Temple\nwithout imparting the power of\nIchrius to anyone else.\nThe High Elves built many temples\nin this area in honor of Ichrius,\nbut most of them are gone now.",
        ["T535"] = "Orladin himself was cloaked in\nmystery, but he did disciple two\nelves, Thedek and Shudom. I hear\nhe taught various disciplines of\nmagic and nature to them.",
        ["T536"] = "He'd done a lot of research on\nthese subjects, but none of it\nhad ever been passed along.\nFortunately, Thedek and Shudom\ndid pass along the results of\ntheir research as well as what\nthey had learned from Orladin.",
        ["T537"] = "The Pedestal of Ichrius has been\nabandoned in the ruins, but if\nyou have the Key of Ichrius, you\nmay still be able to go near the\nsource of power protected by\nOrladin.",
        ["T538"] = "The High Elves say Orladin had a\ngreat power. But we know very\nlittle of him.",
        ["T539"] = "All we know is that he had\nmastered all five principles of\npower. He was very powerful, but\nwe know nothing of what he\ninherited from Ichrius.",
        ["T540"] = "Even though all the truth may be\nfound in this place, it will be\nextremely difficult to actually\nuncover it!",
        ["T541"] = "I'm convinced this nation could\nlive again if only we could\nharness the power of Orladin.",
        ["T542"] = "I have no idea which way to turn.",
        ["T543"] = "I'm sure this country will be\nsaved....The new king has arrived\nand new traditions have emerged.\nI wonder if what I'm saying to\nyou will be remembered as\nhistory.",
        ["T544"] = "I must go now, I plan to recruit\nnew students and begin a career\nof research and study...many\nthanks to you, Prince Austin Lyle\nForester! Our next and greatest\nking!",
        ["T548"] = "You're the prince who was with\nLeon, right? I thought so...well,\nI don't feel like talking to you.\nGo beguile someone else with your\nsweet words and forked tongue...\nget out of here!",
        ["T549"] = "'''''''''''''''''''''''''''''''''",
        ["T550"] = "Thank you for helping Airon. I'm\nsorry for my harsh words before.\nI had no intention of helping\nanyone in the royal family after\nwhat the king has done to us, but\nI'll make an exception for you\nnow. How can I be of service?",
        ["T551"] = "I've been carving tombstones here\nfor the brave souls whose lives\nhave been claimed by the minions\nof evil. I don't know how much\nlonger I'll have to do this, but\nit's the least I can do for those\nbrave men....Poor souls.",
        ["T552"] = "I wonder when the end will\ncome....",
        ["T553"] = "Try not to think too hard. Just\nkeep following the path you are\non -- I'm sure you'll find some\npositive results soon.",
        ["T554"] = "I'd like to be able to trust you,\nLyle. Maybe you'll give me a\nreason to have hope again.",
        ["T555"] = "You know, you don't look very\npowerful....Not too many people\nare left here in this kingdom,\nbut they all regard you as their\nking now that you've shown them a\nreason to hope.",
        ["T556"] = "If you're going to rescue the\nlast of your people, you must\nfulfill your destiny. Mleaning\ntake the powers you've been given\nto the castle and take back the\nkingdom from your former father.\nPlease don't fail us, Lyle...",
        ["T564"] = "I'm the loyal subject of his\nmajesty, King Harvine. The King\nbestowed upon me the honor of\nprotecting this place. My name\nis John Creel, and I've been\nguarding the palace for the last\n300 years....State your business.",
        ["T565"] = "I cannot allow anyone to pass\nunless he is endowed with the\nMagical Power of Wind.",
        ["T566"] = "You may pass now. The King's\nservants will escort you.",
        ["T567"] = "I can tell you nothing of those\nwho have passed here before you.",
        ["T568"] = "Since the death of King Harvine,\nthis palace has been covered in\ndarkness.",
        ["T569"] = "If only all the lamps could be\nlit, the palace would regain its\nlight. You will be able to obtain\nthis gift from the King...if\nyou're worthy.",
        ["T570"] = "Please be cautious...many are the\nperils of this place. Many have\nentered, but no one has returned\nto the light.",
        ["T571"] = "Is it possible that your power\nhas surpassed even that of my\nlord, King Harvine?",
        ["T572"] = "The Ryu-Ga and the Shiden are\ntwo of my master's swords. I\ntook the Ryu-Ga to a place\noverlooking the ocean. It was\nmeant to be a royal gift. He\nwould be delighted if you would\ntake that sword for your own.",
        ["T573"] = "Please feel free to use it when\nan opportunity comes.",
        ["T574"] = "I hope to see you again sometime.",
        ["T575"] = "Many things have been stolen from\nthe palace over these past 300\nyears. But there are still some\nitems left.",
        ["T576"] = "Every item is very precious. Some\nof them are favorite items\nbelonging to the king. Do not\nforget to take these items with\nyou.",
        ["T577"] = "If you rule this continent, may I\npledge now that I will serve you\nas your loyal subject.",
        ["T578"] = "I bid you good luck.",
        ["T580"] = "...Lyle?...But how?...Toni?\nThen she is responsible for\nsaving me...thank you! Thank you\nfor delivering me from a living\ndeath -- a fate worse than the\nthousand deaths I must have\nwitnessed in my stone prison.",
        ["T581"] = "I was on my way to the castle and\nI remember...demons suddenly\nattacked me. I held them at bay\nat first, but then...they turned\nme into stone. How ironic it is\nto be rescued by someone I was\nsupposed to help.",
        ["T582"] = "Take this , it is the Wing of\nIchrius which I have received\nfrom the king. You will be a king\nsoon yourself! You must take\ncare so that nothing happens to\nyou.",
        ["T583"] = "I've finished my task at long\nlast! How painful it has been\nwatching my friends and soldiers\ndying all around me...'twas truly\na sentence worse than death.\nEven when Silviera came here, I\ncould do nothing for him.",
        ["T584"] = "He went to the castle alone...he\nhad decided that the only way to\nstop this madness was to kill the\nKing. Did he ever return from the\ncastle? I feared he wouldn't....\nI would liked to have gone with\nSilviera to fight by his side.",
        ["T585"] = "I wanted more than anything to\nbreak out of my stone tomb and go\nwith him...but I'd been cursed to\nwatch that final battle as well.\nSilviera loved the King before\nthe transformation -- he left\nhere in turmoil.",
        ["T586"] = "But I am old, and there is no way\nI can go to kill the King for\nwhat he has done. I will have to\nleave everything for you to carry\nout. Mleanwhile, I will stay here\nand protect these children as\nbest I can.",
        ["T587"] = "How pitiful that I was turned\ninto stone!",
        ["T588"] = "While I was standing here as a\nstone statue, I witnessed\ncountless villagers being killed\nand eaten by those wicked demons.\nBut what of my vengeance now?\nKilling the King won't bring back\nthe dead.",
        ["T589"] = "I suppose that the least I can do\nis to ensure that these children\nhave the future that was taken\nfrom so many at the hand of all\nthis wickedness. While I'm alive\nI'd like to see peace in this\ncountry again.",
        ["T590"] = "Until peace returns, I shall make\nsure that these children are\nsafe!\nLet's all pray that we shall have\npeace again soon!",
        ["T591"] = "How about a lesson before you go?\nI miss your grandfather, Houser.\nWe used to have so much fun sword\nfighting with each other! Ah...\nthe memories....",
        ["T592"] = "This is about all I can teach you\nnow, but come back again! You'll\nsoon be even better than I am.\nPlease come back though, I'd like\nto chat with you again before I'm\ntoo old....",
        ["T593"] = "When the king was about your age,\nhe made amazing progress in his\nswordsmanship. I remember those\ndays with such fondness...but\nthose times are gone now. Sorry,\nI tend to dwell upon the past a\nlot now. I must be getting old...",
        ["T594"] = "Take care. Please watch every\nstep.",
        ["T595"] = "If your belief in yourself is\nstrong, you'll be able to fulfill\nyour destiny. Alfred is no longer\nthe king he used to be....I\nserved the King for many years,\nand I am convinced of that.",
        ["T596"] = "I'd sure like some good news\nbefore I die....Look how morbid\nI've become after watching so\nmany deaths....",
        ["T597"] = "I almost forgot. Lyle, I'd like\nto give you this sword. An Elf\nmerchant named Elrus -- a friend\nof mine -- told me he had found\nthe sword in the land of Garan.\nPerhaps it will bring you luck!",
        ["T598"] = "He said that he had no use for\nthe sword, and that he wanted to\nthank me for some things I did\nfor him at the castle back then.\nHe could have sold the sword for\na good price, but he gave it to\nme instead.",
        ["T599"] = "He said he'd been looking for\nPromeus. I wonder if he ever went\nback there again....I remember he\nwas accompanied by a small child.\nI've often wondered about that\nchild -- she must be grown by\nnow....I hope she's doing well.",
        ["T600"] = "Soon the reign of the new king\nwill begin. I made a pledge to\nKing Alfred that I would stand\nwith you at the time of your\ncoronation. We've had too many\ndays of misery and hardship, I\nhope you will end it soon.",
        ["T612"] = "You must be Prince Lyle! I\ncan't believe you're finally\nhere! Does this mean the seal\non the castle is broken?!",
        ["T613"] = "Since the day the castle was\nsealed, I've been in hiding. I've\nseen many of my fellow soldiers\neaten alive by these evil\nmonsters, and there was nothing\nI could do.",
        ["T614"] = "To go to the king's Chamber, you\nmust have four corridor keys. My\ncolleague, Endt, has two keys.\nBut he's not here right now...\nhe's off somewhere searching for\nsomething to eat -- probably rats\nagain...",
        ["T615"] = "Maybe we'll get lucky and he'll\nfind us some moldy bread!\nOh ya', the keys...I lost one key\nwhile I was fleeing from one of\nthe monsters.",
        ["T616"] = "But the last key I gave to\nYvette, my girlfriend, the day\nbefore the castle was sealed.",
        ["T617"] = "She's waiting for my return...I\nhope....Anyway, you go ahead\nand get the key from her. I'll\nleave here as soon as Endt\ncomes back.",
        ["T618"] = "Please tell her that I'll be back\nas soon as I can.",
        ["T619"] = "Be careful!",
        ["T620"] = "You must be Prince Lyle! I\ncan't believe you're finally\nhere! Does this mean the seal\non the castle is broken?!",
        ["T621"] = "Since the day the castle was\nsealed, I've been in hiding. I've\nseen many of my fellow soldiers\neaten alive by these evil\nmonsters, and there was nothing\nI could do.",
        ["T622"] = "Really!! You've met Yvette? I'm\nso glad she's all right! In order\nto get to the king's Chamber,\nyou'll need four corridor keys.",
        ["T623"] = "Endt, my colleague, has two of\nthe keys, but he's not here right\nnow...he went off in search of\nsome food -- probably rats\nagain...maybe we'll get lucky\nand he'll find us some moldy\nbread!",
        ["T624"] = "I had the other two keys, but I\nlost one of them. I was being\nchased by one of those monsters,\nand while running, I must have\ndropped it. The final key I left\nwith Yvette...oh, I see you have\nit!",
        ["T625"] = "That's all I can tell you,\nLyle, good luck to you...and\nthank you! I'm going home to\nYvette now! Please be careful.",
        ["T626"] = "Take care!",
        ["T628"] = "Shudom, the Spirit of the Earth,\nis my lord. He made the clay\ndolls out of earth long ago....\nAs the dolls increased in number,\nthey became living things without\nintelligence.",
        ["T629"] = "Once alive, and with their\nnumbers continuing to increase,\nthey began to attack everything\n...even their creator, Shudom.\nWe, the Giants, tried in vain to\nfight against the Golems. But\nthey multiplied too quickly...",
        ["T630"] = "We began to lose the battle, and\nnow we nearly extinct. Lord\nShudom deserted this cave as\nthings became unmanageable. He\ntook our now only surviving\nbrother and left for an island\nfar to the north.",
        ["T631"] = "If you could wipe out the Golems,\nI would open the door which will\nlead to the power of Shudom.",
        ["T632"] = "The time has not come yet.",
        ["T633"] = "The Golems are destroyed?! You\nwill truly be a mighty king...\nThank you for granting my wish.\nReceive the power of my lord as I\npromised. I shall have peace at\nlast!",
        ["T644"] = "After Guyra was defeated by\nAlexander, he tried to recover in\nthe depths of his tomb. But\nbecause of Mlerrill Ur's victory\nover them, the hope of recovery\ndiminished.",
        ["T645"] = "Guyra's consciousness is filled\nwith hatred against Seath. It\nexists solely for the hope that\nGuyra's sword will be restored.",
        ["T646"] = "Guyra and Merrill Ur (who was\ncalled back from the dead) are\namongst the most loathsome and\nlowly creatures in existence...I\npity them.... But even more, I\npity King Alfred. May his soul\nsoon be put to rest.",
        ["T647"] = "Why am I not allowed to die?\nWhat am I waiting for?",
        ["T648"] = "Just a little longer...then\nGuyra's consciousness will.......",
        ["T660"] = "This world of Valicia was created\nby Sylval. Sylval put Elwin to\nrule over the ocean, Elfos to\nrule over the sky, and Vallad\nto rule over the earth.",
        ["T661"] = "After many years, Elwin and Elfos\nreturned to Sylval. Only Vallad\nremained on the earth to rule.",
        ["T662"] = "Vallad created the Elves and the\nDwarfs to inhabit Valicia. Next\nhe created the other creatures\nand later, men.",
        ["T663"] = "They all lived in peace at first.\nBut soon, men began to drive the\nElves and the Dwarfs to remote\nplaces. Mlen began to fight among\nthemselves, and Valicia was\nthrown into turmoil.",
        ["T664"] = "After careful contemplation,\nVallad revealed himself to men as\nSeath and Guyra. Seath became the\nobject of worship, and Guyra\nbecame the object of hatred.\nVallad was pleased at first...",
        ["T665"] = "But Seath and Guyra soon began to\ncompete with each other and lost\nsight of the missions given to\nthem by Vallad. Evil creatures\nwere produced during the struggle\nbetween them, and Valicia began\nto fill with wars and malice.",
        ["T666"] = "The wish of Vallad was then to be\ncarried out by Ichrius, the High\nElf, who instructed Orladin to\ngive his power to whoever would\ndefeat Seath and Guyra once and\nfor all.",
        ["T667"] = "Now the power shall be\ngiven to you. You shall be the\nsavior of this land....Vallad's\nwish will be done!",
        ["T676"] = "The power of the seal for\nwhich Alexander gave his life\nis growing weaker....The number\nof evil creatures is steadily\ngrowing larger. All too soon,\nthe seal will be weak enough to\nbe broken by King Alfred....",
        ["T677"] = "If we allow that to happen, the\ncountry will be enveloped by\ntotal darkness as your former\nfather unleashes his power and\n10 years of pent up rage on\nthis land.",
        ["T678"] = "For the past 10 years, since\nthe fateful day of the seal, I\nhave been watching you grow. I\nam excited but at the same time\nafraid that the day has finally\ncome for you to fulfill your\ndestiny.",
        ["T679"] = "Please take with you this final\nsword, the Excellector. I am\npraying that your journey will\nbe guided by the light.",
        ["T680"] = "Alexander lost his magical power\nof light on the day he placed the\ngreat seal on the castle...all\nhis life force was put into the\nseal. Because you have the blood\nof King Alfred, you have\ninherited that power as well.",
        ["T681"] = "The four other magical powers\nhave been entrusted to four\nArchmages, who have been waiting\nto endow them upon you.",
        ["T682"] = "You must have the four magical\npowers to obtain the Moleonlight\nSword, with which you can break\nthe seal of the castle.",
        ["T683"] = "The four Archmages put the sword\nin the tomb of Alexander and\nsealed it so that none but the\none with all four powers could\nopen it. Besides these powers,\nyou must also obtain the Seals of\nIchrius.",
        ["T684"] = "The king must have given them to\nsomeone for safe keeping. I'll\ntell you about Ichrius later...\njust remember that you must have\nthe three Seals of Ichrius in\norder for you to fulfill your\ndestiny.",
        ["T685"] = "The Excellector, will grow with\nyou and increase in its power\njust as you do. One day you will\nneed its power. When you have the\nthree Seals of Ichrius, bring\nthem to me along with this sword.",
        ["T686"] = "Let me tell you about Ichrius.\nTurcotte Ichrius is the ancestor\nof all Elves. Several thousand\nyears ago, he discovered\nsomething when he found the\nDragon King Plant in the East\nland of Verdite.",
        ["T687"] = "But no one knows exactly what it\nwas that he found....Since that\ntime, he had been working almost\nincessantly to fashion and create\nthe three seals which now bear\nhis name, the Seals of Ichrius.",
        ["T688"] = "In addition to the seals, he\nbuilt many buildings in verdite.\nThere are springs built in the\nbuildings, (unfortunately the\nspring in Quist is now broken).",
        ["T689"] = "Once acquired, the Three Seals of\nIchrius will become one and will\nbe ready....The Great Seal of\nIchrius will then be fashioned\ninto the Key to Ichrius' power\nand springs.",
        ["T690"] = "But the only one who can make the\nkey is an Elf craftsman. The\ntechnique has been handed down\nfor generations among them. I am\nthe only one left in this country\nwho has the skill to craft the\nkey.",
        ["T691"] = "But I can't make it by myself. I\nwill need the sword I gave you.\nAs I said, the sword will grow\nwith you...when it is fully\ngrown, it will exhibit its full\npower!",
        ["T692"] = "As I recall now, the King called\nme not long before he changed. He\ntold me something at that time\nwhich indicated his foreknowledge\nof the present time. These were\nhis last words to me:",
        ["T693"] = "\"I may not be able to keep peace\nin my kingdom. When Lyle becomes\nthe next new king, he will need\nthe Key of Ichrius. I want you to\nfashion it for him. I gave my 3\nmost faithful servants care over\nthe Seals of Ichrius long ago.\"",
        ["T694"] = "Lyle, that fateful day is fast\napproaching when you will need\nthe key. Make haste to find all\nthe seals.",
        ["T695"] = "You met Varde, the chief of the\nwoods, right? I hear while\neveryone deserted and fled to\nother countries, he alone\nremained in the woods.",
        ["T696"] = "Varde also knows that Seath is\nnot really holy. I know, I\nshouldn't be talking like that\nsince I'm an Elf. The Elves have\nbeen worshipping him for several\nthousand years now...but anyway.",
        ["T697"] = "If you met with Varde, I'm sure\nyou've heard about Orladin. I\nhope you understand now how\nIchrius and Orladin have become\nthe key of destiny in this time\nand place.",
        ["T698"] = "Please understand that Varde and\nI are not the only ones who are\nputting our trust and hope in\nyou.",
        ["T699"] = "Go and obtain the remaining Seals\nof Ichrius. Bring them to me\nquickly -- for time is short!",
        ["T700"] = "Time is running out fast!",
        ["T701"] = "Excellector does not give out\nenough power yet. It needs to\ngrow a little more before it can\nexhibit the true power needed.",
        ["T702"] = "Return when both you and the\nExcellector are ready.",
        ["T703"] = "Don't enter the castle yet...you\nneed some more time before you\nwill be ready, and besides, I'll\nbe needing to work the seals into\nIchrius' Key. I'll keep the sword\nand the seals for now.",
        ["T704"] = "Once I've completed the key, you\nwill take it to the Valley of\nEternity to obtain the power of\nIchrius. Only then will you be\nready! I will make it quickly.\nI'll keep you informed on the\nprogress. Come back soon.",
        ["T705"] = "I may need a little more time.",
        ["T706"] = "Please wait for a moment.",
        ["T707"] = "It will be finished shortly.",
        ["T716"] = "I didn't know who I was or where\nI was going. I was afraid. I knew\nnothing....I was called the\ngreatest Archmage, Orladin, and\nyet I was scared.",
        ["T717"] = "I inherited all that Ichrius had\nto offer, and yet I had nothing\nthat I could accomplish. When I\nwas told that my sole duty in\nlife was simply to wait, I ceased\nto live. I was just a watchman\nfor Vallad.",
        ["T718"] = "That was my fate...I didn't need\nto be alive to do that. I must\nsend you off now to accomplish\nyour mission. But before you go,\nI would like to give you a gift.",
        ["T719"] = "You are this land's best hope...\nnow that you know which path to\npursue, go! Fulfill your destiny\nand become king.",
        ["T732"] = "Go away imposture -- I'm the real\nPrince Austin Lyle Forester.",
        ["T733"] = "In this passage, I was told in a\ndream by Vallad that I would find\nthe secret of the Light Family...",
        ["T734"] = "It's you again. Why don't you get\nlost?! You're not fooling anyone\nwith that silly looking costume.\nGuards!! Take him away!",
        ["T735"] = "''''''''''''''''''''''''''''''",
        ["T736"] = "I know if I hold this candle up\nlong enough, the will of Vallad\nwill disintegrate this wall and\nreveal the key to me! I have the\ndivine right to that treasure and\nit will be mine...oh yes, it will\nbe mine -- hee-hee-hee-hee-hee...",
        ["T737"] = "You think I'm crazy, but I know\nbetter. In this passage...a\nsecret is hidden. I don't know\nwhat it is, but I've been given a\nvision of it by Vallad...you\ncan't take it from me, no one can\ntake it from me...it's all mine.",
        ["T738"] = "You see, a long time ago,\nmerchants from the Light family\nused to come to the back of this\npassage. I don't know what they\nwere doing here...I found nothing\nthere except some poison....",
        ["T739"] = "I wonder what I'll find in here.",
        ["T740"] = "I want to check it out, but I'm\nafraid if I get poisoned again, I\nmight turn back into a glass of\norange juice and someone will\nspill me.",
        ["T741"] = "The Light Family members were the\nmost prosperous merchants in this\narea of Verdite three generations\nago...I taught them everything\nthey knew, you know...",
        ["T742"] = "There used to be commercial signs\nfor the Light Family all over the\nplace. I know, because I wrote\nthem! People say they and the\nKing were in cahoots about a lot\nof shady deals.",
        ["T743"] = "The merchants began to decline in\ninfluence about the time King\nAlfred began his reign.\nApparently, they all moved to\nother countries after their royal\nconnection was cut off.",
        ["T744"] = "Vallad told me that the Light\nMlerchants were engaged in lots of\nshady deals. I guess that's why\nthey would have come to a strange\nplace like this -- to find some\nshade from the sun.",
        ["T745"] = "I'm curious what I will really\nfind in this place.",
        ["T746"] = "There are some Slimes here in\nthis passage. You'll need\nantidote plants but don't count\non their effectiveness too much.\nYou'd do best to have a silver\nring. Would you like mine? What\ndo you mean it's a gum wrapper!?",
        ["T747"] = "I've never been so insulted! I'm\na prince, you know, have some\nrespect. I was going to tell you\nthat if you go through this\npassage, you'll come to Lake\nNoel, but now I'm not going to.\nThe lake used to be so beautiful.",
        ["T748"] = "It was a fitting tribute to the\nbeauty of the queen. You can't\ncross it now -- the bridges over\nthe lake have all been destroyed\n-- only I can cross it with the\nspecial boots. I wonder when\nVallad is coming with the key....",
        ["T752"] = "I'm Franz, a student of Master\nLicht. My teacher has been\nengaged in research for Orladin\nfor a number of years...what a\ngreat and wonderful quest!",
        ["T753"] = "I hope something can be done with\nour research, the country is in\nsuch disarray....",
        ["T754"] = "Along this corridor, they say\nmany unscrupulous merchants and\nArchmages have hidden many\ntreasures. Those who fled the\ncountry hid things here that they\ncouldn't carry with them.",
        ["T755"] = "Many of them set traps when they\nleft their valuables. This is an\nextremely dangerous place. People\nbegan to stay away from here and\nnow only thieves come here to\nrisk their lives for the unknown\ntreasures.",
        ["T756"] = "For that reason, this corridor is\nnow called the Path of Robbers.\nI had followed my master to this\nplace, but because of the demons,\nI couldn't proceed any further.",
        ["T757"] = "My master used to say, \"Orladin's\nTemple of Maze must be in the\nruins of the High Elves.\" But I\nhaven't even found out where the\nruins might be yet.",
        ["T758"] = "Orladin used to play tricks on\npeople. Actually, some even lost\ntheir lives.",
        ["T759"] = "The master kept moving ahead, and\nwe got lost several times. He was\nobsessed with the research of\nOrladin. Sometimes he would even\nforget about me completely.",
        ["T760"] = "I sure hope my master is okay.\nPlease be careful.",
        ["T761"] = "I'm so glad to know he is safe.",
        ["T762"] = "Now that he is found, I'll begin\nstudying with my master again.",
        ["T768"] = "I'm Tim, a traveling merchant. I\nhad heard that the Dwarfs dwelt\nin this eastern section, so I\ncame here to try to find them...I\nwanted to buy armor from them,\nbut now I'm stuck.",
        ["T769"] = "Unfortunately, I can't get past\nthis lake. The bridge that used\nto span these waters is gone, and\nI've heard that you have to have\nsome special boots to go across\nthe strange bridge which took its\nplace.",
        ["T770"] = "I thought that with good\nprotective armor I'd be safe from\nthe evil creatures. But sometimes\nI wonder if it's all in vain.",
        ["T771"] = "I'd be glad to give you mine; I\ndon't think I'll be needing it\nanymore. It's not as good as the\nones made by the Dwarfs. But\nit'll do.",
        ["T772"] = "This country has such beauty.\nI'd consider living here if it\nweren't for the monsters\neverywhere.",
        ["T773"] = "We don't have the luxury of being\nable to move to other countries\nany more.",
        ["T774"] = "Lake Noel was named after Queen\nNoel. I understand she was a\nqueen of exquisite beauty.",
        ["T775"] = "I don't know who you are -- I\nsuppose it's really none of my\nbusiness. But you look way too\nserious. May I give you a piece\nof advice? You need to relax and\nlighten up a little.",
        ["T776"] = "I look forward to chatting with\nyou some day when peace returns\nto this country.",
        ["T777"] = "I'm beginning to be convinced\nthat the good old days of peace\nand happiness will return here as\nlong as there are people like\nyou!",
        ["T778"] = "Take care!\nSee you soon.",
        ["T784"] = "I've been living here for over\nfive years now. When the\nCommander headed for the castle,\nI had to remain here alone\nbecause I was wounded. Do you\nhave any idea what it means to a\nsoldier to be left behind...",
        ["T785"] = "do you understand the anguish\nI've gone through -- how deeply\nI regret not dying from that\nwound? After my wound healed, I\nbegan to dig graves for my fallen\ncomrades.",
        ["T786"] = "But I've been waiting for my\nCommander's return for over five\nyears now, and I'm completely\nexhausted. I wish I'd just be\ngranted the death I deserved so\nlong ago.",
        ["T787"] = "In these underground barracks,\nCommander Silviera made several\ntraps for training purposes...not\nmuch time for training, I'm\nafraid. ...Molest of the soldiers\ndied before they ever even knew\nabout the training or the traps.",
        ["T788"] = "In front of the jail you could\nsee a target. All you would have\nto do is pull back the bow string\nand the arrow would hit the\ntarget. You can't really call\nthem soldiers. Molest of them were\ncommon villagers.",
        ["T789"] = "They made poor fighting men,\nbut they all loved Silviera. When\nthe villagers made the statue of\nthe Commander, I remember them\nsaying something about setting a\ntrap for the Commander's sword.",
        ["T790"] = "It was a trap to test the next\nrecipient, so that anyone smart\nenough and strong enough to\nfigure out the trap could obtain\nthe sword. The Silvarion was\nanother of the Commander's\nswords.",
        ["T791"] = "It was one of the most prized\nswords, given only to the best\nswordsman. It was awarded along\nwith the title of Sword Master. I\nbelieve the sword was given to\nthe Commander by another\nCommander -- Lord Veyrac.",
        ["T792"] = "Sword Master Houser, the King's\nfather, used the same sword. Our\nCommander was a brave warrior\nwith a special ability to devise\ncomplicated traps.",
        ["T793"] = "There were many make-shift\nsoldiers here. We found solace in\nour conversation as friends. How\ndreadfully things have turned out\nto be!",
        ["T794"] = "I was with Commander Silviera at\nthe castle; I served our king as\na guard before the\ntransformation. Ten years ago,\nwhen the king recovered from\nbeing sick, he no longer looked\nhuman.",
        ["T795"] = "I wonder what happened to the\nsoldiers who were sealed inside\nthe castle. I hear the evil\ncreatures inside the castle like\nto eat human flesh. They are\nmighty foes to contend with.",
        ["T796"] = "To this day I have no idea what\nhappened to the King. Even if\npeace returns to this country,\nnothing will ever replace the\nemptiness in my heart for my\nfallen comrades.",
        ["T797"] = "Oh...that this too too solid\nflesh would melt.... During the\nendless and miserable days of\nbattle, some soldiers began to\nflee. The Commander was saddened,\nbut he had a special prison built\nfor soldiers who fled....",
        ["T798"] = "One day the key to this special\nprison was stolen from the\nCommander's desk.....",
        ["T799"] = "In the midst of a great battle,\nwe were being forced back....\nWe couldn't get the soldiers out\nof the prison without the key,\nand the enemy was advancing\ntoo fast to remain.",
        ["T800"] = "We were forced to leave the\nsoldiers in the prison -- they\nwere all slaughtered. Every\nsingle one of them -- I bet the\nking, himself, dined on their\nflesh that night.",
        ["T801"] = "We have some powerful weapons\nhere fashioned by the Dwarfs and\nthe Elves. These weapons assisted\nus during the battle, but now\nthey lay unused among the dead.",
        ["T802"] = "There were some other weapons\nmade by Master Craftsman Jens.\nBut they were too heavy for the\nhumans to use. Those weapons are\nall scattered unused and waiting\nfor the next one powerful enough\nto wield them.",
        ["T803"] = "I remember the Commander talking\nabout it...he said that when the\ntime came, he would now have to\nteach Lyle swordsmanship...Lord\nknows his father could no longer\ndo it.",
        ["T804"] = "The King is gone. Alexander is\ndead. And the Commander has\ndisappeared. Now  the only one\nwho can teach swordsmanship is\nLord Veyrac, who was a friend of\nthe King's father.",
        ["T805"] = "I believe Lord Veyrac is still\nfighting somewhere....",
        ["T806"] = "I wonder if I'm going to die in\nthis desolate place.",
        ["T807"] = "Let me tell you about the\nimportant swords you need to know\nof. I told you about Silvarion\nand Capricorn.",
        ["T808"] = "There is also the Dark Slayer\nwhich belonged to Guyra, the\nMoleonlight Sword which belonged to\nSeath, the sword owned by Mlerrill\nUr -- the swordsman of the High\nElves, and also the Triple Fang\nwhich belonged to the King.",
        ["T809"] = "Hmm, there are some more....The\nLong Sword which Caine, the vice\nCommander, used to own, had the\nname \"Flame\" engraved on it.",
        ["T810"] = "That one was also famous...I\nhave no use of swords anymore,\nbut I would like to see some of\nthem some day. The Commander\ncould use any of those swords in\ncombat. What a swordsman he was!\nI wonder how he's doing.",
        ["T811"] = "I hope I'm not going to waste\naway here much longer. I long\nto fight by his side.",
        ["T816"] = "I'm very sorry about Lyn, but she\nhas done well for herself. It was\nLord Veyrac's wish also that she\nwould be cared for...Did she tell\nyou how she felt about you before\nshe... ...",
        ["T817"] = "Well enough of that; the\ntechniques of swordsmanship that\nI shall now teach you will help\nyou in your final hours with he\nwho was formerly your father.",
        ["T818"] = "Finally the time has come. Do not\nregard the one in the castle as\nyour father. Your tomb there was\nmade by those who desire to take\nyour life.",
        ["T819"] = "The holy sword you carry is not\nthe correct one, you will need\nthe power of the Sword of Light.\nGuyra will endow the light upon\nthe sword once again.",
        ["T820"] = "Your subjects are awaiting you.\nFor the sake of your people, you\nmust regain the light for this\ncountry. Your true father wishes\nthat as well.....",
        ["T835"] = ".. . . . ....... . . . .",
