        ["I181"] = "The Sacred Land of\nthe High Elves\nQuist",
        ["I182"] = "You are Entering Ralugo\nBirthplace of\nHoly King Alfred I",
        ["I183"] = "The Village of Cason",
        ["I184"] = "No Entrance\nThe Royal Cemetery",
